const kvFooterTemplate="<footer class=\"kf-footer\" role=\"contentinfo\">\n<div class=\"kf-foot-container\">\n <div class=\"kf-foot-top\">\n  <div class=\"kf-foot-brand\">\n   <a class=\"kf-foot-logo\" href=\"/\" aria-label=\"Karunvaya Foundation homepage\">\n    <img src=\"/assets/karunvaya-foundation-logo.jpg\" alt=\"\" width=\"52\" height=\"52\" loading=\"lazy\" decoding=\"async\">\n    <span>Karunvaya<br>Foundation</span>\n   </a>\n   <p class=\"kf-foot-tagline\">Education. Social welfare. Compassion and dignity for every community.</p>\n  </div>\n  <div class=\"kf-foot-links\">\n   <nav class=\"kf-foot-col\" aria-label=\"Explore Karunvaya\"><h3>Explore</h3>\n    <a href=\"/about.html\">About us</a>\n    <a href=\"/education.html\">Education</a>\n    <a href=\"/social-welfare.html\">Social welfare</a>\n    <a href=\"/social.html\">Social media</a>\n   </nav>\n   <nav class=\"kf-foot-col\" aria-label=\"Get involved\"><h3>Get involved</h3>\n    <a href=\"/volunteer.html\">Become a volunteer</a>\n    <a href=\"/donate.html\">Support our mission</a>\n    <a href=\"/contact.html\">Contact us</a>\n    <a href=\"/social.html#whatsapp\">WhatsApp</a>\n   </nav>\n  </div>\n </div>\n <div class=\"kf-foot-bottom\">\n  <nav class=\"kf-foot-legal\" aria-label=\"Policies\">\n   <a href=\"/terms.html\">Terms</a>\n   <a href=\"/privacy.html\">Privacy</a>\n   <a href=\"/refunds.html\">Donation &amp; refunds</a>\n   <a href=\"/safeguarding.html\">Safeguarding</a>\n  </nav>\n  <nav class=\"kf-foot-social\" aria-label=\"Official social media channels\"><!--KF_SOCIAL_ICONS--></nav>\n </div>\n <small class=\"kf-foot-copy\">© <span id=\"year\">2026</span> Karunvaya Foundation · Education &amp; Social Welfare</small>\n</div>\n</footer>";
function kvCompactFooter(env){
 const social=kvSocialSpecs.map(a=>{
  const link=kvSocialExternalUrl(env,a);
  const href=link||"/social.html#"+a.id;
  const hint=link?"Official "+a.name:a.name+" page details";
  return '<a href="'+href+'"'+(link?' target="_blank" rel="noopener noreferrer"':'')+' title="'+hint+'" aria-label="'+hint+'">'+a.icon+'</a>';
 }).join("");
 return kvFooterTemplate.replace("<!--KF_SOCIAL_ICONS-->",social);
}

const KV_ORIGINAL = {
 async fetch(request,env,ctx){
  const url=new URL(request.url);
  if((url.pathname==="/social.html"||url.pathname==="/social")&&request.method==="GET")return kvSocialHubPage(env);
  if(url.pathname==="/__kv-social.css")return new Response(kvSocialCss,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-footer.css")return new Response(kvFooterCss,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/api/site/contact"||url.pathname.startsWith("/api/admin/enquiries"))return kvContactAPI(request,env);
  if(url.pathname==="/api/site/overview")return kvPublicOverview(request,env);
  if(url.pathname==="/api/pan/config"||url.pathname==="/api/pan/verify")return panApi(request,env);
  if(url.pathname==="/api/payments/order")return panOrderGate(request,env);
  if(url.pathname==="/__kv-volunteer-modal.css")return new Response(css,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-volunteer-modal.js")return new Response(js,{headers:{"content-type":"application/javascript; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-pan-gate.css")return new Response(panCss,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-pan-gate.js")return new Response(panJs,{headers:{"content-type":"application/javascript; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-festive.css")return new Response(festiveCss,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-festive.js")return new Response(festiveJs,{headers:{"content-type":"application/javascript; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-premium.css")return new Response(premiumCss,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-professional.css")return new Response(professionalCss,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-professional.js")return new Response(professionalJs,{headers:{"content-type":"application/javascript; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-contact.css")return new Response(secureContactCss,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-contact.js")return new Response(secureContactJs,{headers:{"content-type":"application/javascript; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-admin-contact.css")return new Response(secureAdminCss,{headers:{"content-type":"text/css; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  if(url.pathname==="/__kv-admin-contact.js")return new Response(secureAdminJs,{headers:{"content-type":"application/javascript; charset=utf-8","cache-control":"public, max-age=300","x-content-type-options":"nosniff"}});
  const response=await env.BACKEND.fetch(request);
  const type=response.headers.get("content-type")||"";
  if(request.method!=="GET"||!type.toLowerCase().includes("text/html")||response.status>=400)return response;
  const donationRoute=/^\/(?:donate|donation|donations|support)(?:\.html)?\/?$/i.test(url.pathname);
  const homeRoute=url.pathname==="/"||url.pathname==="/index.html";
  const contactRoute=url.pathname==="/contact.html"||url.pathname==="/contact";
  const adminRoute=url.pathname==="/admin.html"||url.pathname==="/admin";
  const privacyRoute=url.pathname==="/privacy.html";
  const publicRoute=!/^\/(?:admin|dashboard|account|my-volunteer-panel|login|register|receipt)(?:[/.]|$)/i.test(url.pathname);
  let panInserted=false,luxeInserted=false,ribbonInserted=false,proInserted=false,contactInserted=false,privacyInserted=false;
  return new HTMLRewriter()
  .on("head",{element(el){
   const existing='<link rel="stylesheet" href="/__kv-volunteer-modal.css?v=2"><script defer src="/__kv-volunteer-modal.js?v=2"></script>';
   const pan=donationRoute?'<link rel="stylesheet" href="/__kv-pan-gate.css?v=4"><script defer src="/__kv-pan-gate.js?v=4"></script>':'';
   const festive=publicRoute?'<link rel="stylesheet" href="/__kv-festive.css?v=1"><script defer src="/__kv-festive.js?v=1"></script>':'';
   const professional=publicRoute?'<link rel="stylesheet" href="/__kv-professional.css?v=1"><script defer src="/__kv-professional.js?v=1"></script>':'';
   const contact=contactRoute?'<link rel="stylesheet" href="/__kv-contact.css?v=1"><script defer src="/__kv-contact.js?v=1"></script>':'';
   const admin=adminRoute?'<link rel="stylesheet" href="/__kv-admin-contact.css?v=1"><script defer src="/__kv-admin-contact.js?v=1"></script>':'';
   const premium='<link rel="stylesheet" href="/__kv-premium.css?v=2">';
   const social=publicRoute?'<link rel="stylesheet" href="/__kv-social.css?v=1">':'';
   const footerStyle=publicRoute?'<link rel="stylesheet" href="/__kv-footer.css?v=1">':'';
   const canonical=publicRoute?'<link rel="canonical" href="https://karunvaya-foundation.pages.dev'+url.pathname.replace(/[^a-zA-Z0-9/_.-]/g,'')+'">':'';
   el.append(existing+pan+festive+professional+contact+admin+premium+social+footerStyle+canonical,{html:true});
  }})
  .on('a[href="/impact.html"]',{element(el){el.setAttribute("href","/about.html");}})
  .on('a[href="/transparency.html"]',{element(el){el.setAttribute("href","/privacy.html");}})
  .on("#krf-festival-style",{element(el){if(publicRoute)el.remove();}})
  .on(".krf-festival",{element(el){if(publicRoute)el.remove();}})
  .on(".notice",{element(el){if(publicRoute&&!ribbonInserted){ribbonInserted=true;el.replace(seasonalBar,{html:true});}}})
  .on("main",{element(el){
   if(homeRoute&&!luxeInserted){luxeInserted=true;el.prepend(festiveHtml,{html:true});}
   if(contactRoute&&!contactInserted){contactInserted=true;el.append(secureContactHtml,{html:true});}
   if(privacyRoute&&!privacyInserted){privacyInserted=true;el.append(contactPrivacyHtml,{html:true});}
   if(publicRoute&&(homeRoute||contactRoute))el.append(kvSocialQuickSection(env),{html:true});
  }})
  .on("footer",{element(el){if(publicRoute)el.append(kvSocialFooterBar(env),{html:true});}})
  .on("section.hero",{element(el){if(homeRoute&&!proInserted){proInserted=true;el.after(professionalHtml,{html:true});}}})
  .on("#giving-form fieldset, .donate-planner fieldset",{element(el){
   if(!donationRoute||panInserted)return;panInserted=true;el.after(panHtml,{html:true});
  }}).transform(response);
 }
};

